-- CFOClose staged release transport: bootstrap. GENERATED by scripts/release/stagedTransport.mjs — do not edit.
-- Creates the private schema cfoclose_release. Staged artifacts are inert text: each insert is refused unless its exact
-- UTF-8 byte count and SHA-256 equal one approved artifact of commit daa23e4113dc726fab867480dac6b0b6aba0bbfc; rows are never updated except by
-- the consumption transition inside a batch apply, never deleted, never truncated. No client role can reach anything here.
DO $cfoclose_transport_bootstrap$
DECLARE
  c_predecessor CONSTANT text[] := ARRAY['8122917c23abca8726e7ee763796ffae568179233c9537b61a5aff35310f17bc']::text[];
  v_n bigint;
  v_pred_id bigint;
  v_role text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('cfoclose_release_transport', 0));
  IF to_regclass('drizzle.__drizzle_migrations') IS NULL THEN
    RAISE EXCEPTION 'TRANSPORT_JOURNAL_MISSING: drizzle.__drizzle_migrations is not visible; nothing was changed' USING ERRCODE = '55000';
  END IF;
  SELECT count(*), max(j.id) INTO v_n, v_pred_id FROM drizzle.__drizzle_migrations j WHERE j.hash = ANY (c_predecessor);
  IF v_n <> 1 OR EXISTS (SELECT 1 FROM drizzle.__drizzle_migrations j WHERE j.id > v_pred_id
                           AND j.xmin::text <> (pg_current_xact_id()::text::bigint % 4294967296)::text) THEN
    RAISE EXCEPTION 'TRANSPORT_WRONG_PREDECESSOR: the transport bootstrap must directly follow its approved journal predecessor; nothing was changed' USING ERRCODE = '55000';
  END IF;
  IF v_pred_id <> 64 THEN
    RAISE EXCEPTION 'TRANSPORT_WRONG_PREDECESSOR: the transport bootstrap must follow hosted journal id 64; nothing was changed' USING ERRCODE = '55000';
  END IF;
  IF to_regnamespace('cfoclose_release') IS NOT NULL THEN
    RAISE EXCEPTION 'TRANSPORT_ALREADY_INSTALLED: schema cfoclose_release exists; nothing was changed' USING ERRCODE = '55000';
  END IF;

  CREATE SCHEMA cfoclose_release;
  COMMENT ON SCHEMA cfoclose_release IS 'Release-only staged transport for the financial-statements batches. Not application data; never exposed.';

  CREATE TABLE cfoclose_release.staged_artifacts (
    batch        text        NOT NULL,
    kind         text        NOT NULL CHECK (kind IN ('preflight', 'wrapper', 'postcondition')),
    body         text        NOT NULL,
    body_bytes   integer     NOT NULL,
    body_sha256  text        NOT NULL,
    staged_at    timestamptz NOT NULL DEFAULT clock_timestamp(),
    staged_by    name        NOT NULL DEFAULT session_user,
    consumed_at  timestamptz,
    PRIMARY KEY (batch, kind)
  );
  CREATE TABLE cfoclose_release.transport_events (
    seq     bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    batch   text        NOT NULL,
    event   text        NOT NULL CHECK (event IN ('staged', 'applied')),
    detail  jsonb       NOT NULL DEFAULT '{}'::jsonb,
    at      timestamptz NOT NULL DEFAULT clock_timestamp(),
    by_role name        NOT NULL DEFAULT session_user
  );

  CREATE FUNCTION cfoclose_release.approved_artifact(p_batch text, p_kind text, OUT bytes integer, OUT sha256 text)
    LANGUAGE sql IMMUTABLE SET search_path = pg_catalog AS $fn$
      SELECT a.bytes, a.sha256 FROM (VALUES
        ('fs-controls-r1', 'preflight', 1954, '12246fdb909047f44a46fe1366d4b7a966bc6057535d9e8b0616df61dce0caa0'),
        ('fs-controls-r1', 'wrapper', 94858, '7c3c0b0d9cd456f07a88da1c0930fb5e4a9c4bdeead6ea068008eca939470d56'),
        ('fs-controls-r1', 'postcondition', 3574, 'd57af109ed12acdefdcf0160422cafd4e63a3cdcd8774fc7826bb096174607f3'),
        ('fs-journey-r1', 'preflight', 1916, 'cd96b89774b8b6da832a8915f838ef5442f05cc87dca189cc0898dde5fc77d3f'),
        ('fs-journey-r1', 'wrapper', 73127, '8f7a1a98a0c34a250dbeb2c94a5c6f4f6d9528a0bf4509e8b1ee89649e135fcd'),
        ('fs-journey-r1', 'postcondition', 3510, '2b0b28522203b58ab883814a01119afaacdd5e8ee3f322d7990059cd86fe0415'),
        ('fs-bounds-r1', 'preflight', 2826, '4bbaa482518341d02eff8e20e424d5fafecaf94405e0b1f2437788e1a661b60e'),
        ('fs-bounds-r1', 'wrapper', 15098, '778cfec6f62847def10b7d0938b7aa661ac2c22c2330b40009f3bc0e4682898b'),
        ('fs-bounds-r1', 'postcondition', 3044, '2f6e26999122c9cbb9deb52288ccdf41c1527df7e4cd5ec90b680cc93f83bd2f'),
        ('fs-capacity-r1', 'preflight', 2690, '0e86b0fa2b059e964e369e0166b74ea6c53fe8856ea79307f3269f53fdc9b196'),
        ('fs-capacity-r1', 'wrapper', 57041, 'd156d1aa434d290932c03f868d0a03779456a90cbdc269d473f8a0ecf9510428'),
        ('fs-capacity-r1', 'postcondition', 3590, '6d12b01760bb53029f4a3e9ab2089962d18d1c701c4c5e5b1c4f25229e894822'),
        ('fs-memo-r1', 'preflight', 1322, 'cfc1f5514e72197d7928173e64e5bd35e1e8e9e600c2fa99793fc404fa0e7d9e'),
        ('fs-memo-r1', 'wrapper', 28556, 'f332c8b62ba87d99bc149644dd2e43580a6419f9e2d07a4db90666776a5c0321'),
        ('fs-memo-r1', 'postcondition', 3091, '68c72b99cf80ca35f09cc8a79d6a4b5152025ecab48ed6d3af244224a426c4c1')
